const HEX: &[u8; 12288] = b"";

const fn nibble(value: u8) -> u32 {
    match value {
        b'0'..=b'9' => (value - b'0') as u32,
        b'a'..=b'f' => (value - b'a' + 10) as u32,
        _ => 0,
    }
}

const fn decode() -> [u32; 4096] {
    let mut result = [0u32; 4096];
    let mut index = 0;
    while index < result.len() {
        let offset = index * 3;
        result[index] = (nibble(HEX[offset]) << 8) | (nibble(HEX[offset + 1]) << 4) | nibble(HEX[offset + 2]);
        index += 1;
    }
    result
}

pub(super) const FRUIT_DITHER: [u32; 4096] = decode();
